import{_ as l,a0 as o,w as d,s as r,ao as p,I as e,x as n,a1 as t,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"七个使用 wget 命令的技巧 | LCTT x X-CMD","titleTemplate":false,"description":"七个使用 wget 命令的技巧 | LCTT (202111) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"七个使用 wget 命令的技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"七个使用 wget 命令的技巧 | LCTT (202111) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202111/20211021 7 handy tricks for using the Linux wget command","title":"七个使用 wget 命令的技巧","tag":"202111","desc":""},"relativePath":"202111/20211021 7 handy tricks for using the Linux wget command.md","filePath":"[post].md"}'),g={name:"202111/20211021 7 handy tricks for using the Linux wget command.md"};function c(h,s,u,b,k,m){const a=o("Link");return d(),r("div",null,[s[35]||(s[35]=p(`<h1 id="七个使用-wget-命令的技巧" tabindex="-1">七个使用 wget 命令的技巧 <a class="header-anchor" href="#七个使用-wget-命令的技巧" aria-label="Permalink to “七个使用 wget 命令的技巧”">​</a></h1><blockquote><p>用你的 Linux 终端中从互联网上下载文件。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202111/22/102927pjuji5juxzuikkg6.jpg" alt=""></p><p><code>wget</code> 是一个下载网页文件的免费工具。它将互联网上的数据保存到一个文件或展示在终端上。实际上这也是像 Firefox 或 Chromium 这样的网页浏览器的工作原理。有一个区别是，网页浏览器默认将网页 <ruby>渲染<rt>render</rt></ruby>在图形窗口中，并且通常需要用户主动来操作它们。而 <code>wget</code> 工具是无交互的使用方式，也就是说你可以使用脚本或定期使用 <code>wget</code> 来下载文件，不论你人是否在电脑面前。</p><h3 id="使用-wget-下载文件" tabindex="-1">使用 wget 下载文件 <a class="header-anchor" href="#使用-wget-下载文件" aria-label="Permalink to “使用 wget 下载文件”">​</a></h3><p>你可以通过提供一个特定 URL 的链接，用 <code>wget</code> 下载一个文件。如果你提供一个默认为 <code>index.html</code> 的 URL，那么就会下载该索引页。默认情况下，文件会被下载到你当前的工作目录，并保持原来的名字。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://example.com</span></span>
<span class="line"><span>--2021-09-20 17:23:47-- http://example.com/</span></span>
<span class="line"><span>Resolving example.com... 93.184.216.34, 2606:2800:220:1:248:1893:25c8:1946</span></span>
<span class="line"><span>Connecting to example.com|93.184.216.34|:80... connected.</span></span>
<span class="line"><span>HTTP request sent, awaiting response... 200 OK</span></span>
<span class="line"><span>Length: 1256 (1.2K) [text/html]</span></span>
<span class="line"><span>Saving to: &#39;index.html&#39;</span></span></code></pre></div><p>通过使用 <code>--output-document</code> 和 <code>-</code> 符号，你可以指示 <code>wget</code> 将数据发送到 <ruby>标准输出<rt>stdout</rt></ruby>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://example.com --output-document - | head -n4</span></span>
<span class="line"><span>&lt;!doctype html&gt;</span></span>
<span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span>&lt;head&gt;</span></span>
<span class="line"><span>   &lt;title&gt;Example Domain&lt;/title&gt;</span></span></code></pre></div><p>你可以使用 <code>--output-document</code> 选项（简写为 <code>-O</code>）将下载文件命名为任何你想要的名称：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://example.com --output-document foo.html</span></span></code></pre></div><h3 id="断点续传" tabindex="-1">断点续传 <a class="header-anchor" href="#断点续传" aria-label="Permalink to “断点续传”">​</a></h3><p>如果你正在下载一个超大文件，你可能会遇到中断下载的情况。使用 <code>--continue</code>（简写为 <code>-c</code>），<code>wget</code> 可以确定从文件的哪个位置开始继续下载。也就是说，下次你在下载一个 4 GB 的 Linux 发行版 ISO 时，如果出现了错误导致中断，你不必重新从头开始。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget --continue https://example.com/linux-distro.iso</span></span></code></pre></div><h3 id="下载一系列的文件" tabindex="-1">下载一系列的文件 <a class="header-anchor" href="#下载一系列的文件" aria-label="Permalink to “下载一系列的文件”">​</a></h3><p>如果你要下载的不是单个大文件，而是一系列的文件，<code>wget</code> 也能提供很好的帮助。假如你知道要下载文件的路径以及文件名的通用范式，你可以使用 Bash 语法指示一个数字范围的起始和终点来表示这一系列文件名:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget http://example.com/file_{1..4}.webp</span></span></code></pre></div><h3 id="镜像整个站点" tabindex="-1">镜像整个站点 <a class="header-anchor" href="#镜像整个站点" aria-label="Permalink to “镜像整个站点”">​</a></h3><p>使用 <code>--mirror</code> 选项你可以下载整个站点，包括它的目录结构。这与使用选项 <code>--recursive --level inf --timestamping --no-remove-listing</code> 的效果是一样的，该选项表明可以进行无限制的递归，得到你指定域下的所有内容。但你也可能会得到比预期多得多的内容，这取决于站点本身的老旧程度。</p><p>如果你正在使用 <code>wget</code> 来打包整个站点，选项 <code>--no-cookies --page-requisites --convert-links</code> 非常有用，它可以确保打包的站点是全新且完整的，站点副本或多或少是<ruby>自包含的<rt>self-contained</rt></ruby>。</p><h3 id="修改-html-标头" tabindex="-1">修改 HTML 标头 <a class="header-anchor" href="#修改-html-标头" aria-label="Permalink to “修改 HTML 标头”">​</a></h3><p>在计算机发送的通信报文里含有大量用于数据交换的<ruby>元数据<rt>metadata</rt></ruby>。HTTP 标头是初始数据的组成部分。当你浏览某个站点时，你的浏览器会发送 HTTP 请求标头。使用 <code>--debug</code> 选项可以查看 <code>wget</code> 为每个请求发送了什么样的标头信息:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget --debug example.com</span></span>
<span class="line"><span>---request begin---</span></span>
<span class="line"><span>GET / HTTP/1.1</span></span>
<span class="line"><span>User-Agent: Wget/1.19.5 (linux-gnu)</span></span>
<span class="line"><span>Accept: */*</span></span>
<span class="line"><span>Accept-Encoding: identity</span></span>
<span class="line"><span>Host: example.com</span></span>
<span class="line"><span>Connection: Keep-Alive</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---request end---</span></span></code></pre></div><p>你可以使用 <code>--header</code> 选项修改请求标头。实际上经常使用这种方式来模仿某特定浏览器，来测试或兼容某些编码糟糕、只能与特定代理通信的站点。</p><p>让请求被识别为来自 Windows 系统的 Microsoft Edge：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget --debug --header=&quot;User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36 Edg/91.0.864.59&quot; http://example.com</span></span></code></pre></div><p>你也可以假装为某个移动设备：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget --debug --header=&quot;User-Agent: Mozilla/5.0 (iPhone; CPU iPhone OS 13_5_1 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/13.1.1 Mobile/15E148 Safari/604.1&quot; http://example.com</span></span></code></pre></div><h3 id="查看响应标头" tabindex="-1">查看响应标头 <a class="header-anchor" href="#查看响应标头" aria-label="Permalink to “查看响应标头”">​</a></h3><p>与浏览器发送请求标头的方式一样，响应也包含有标头信息。你可以使用 <code>--debug</code> 选项来查看响应中的标头信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget --debug example.com</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>---response begin---</span></span>
<span class="line"><span>HTTP/1.1 200 OK</span></span>
<span class="line"><span>Accept-Ranges: bytes</span></span>
<span class="line"><span>Age: 188102</span></span>
<span class="line"><span>Cache-Control: max-age=604800</span></span>
<span class="line"><span>Content-Type: text/html; charset=UTF-8</span></span>
<span class="line"><span>Etag: &quot;3147526947&quot;</span></span>
<span class="line"><span>Server: ECS (sab/574F)</span></span>
<span class="line"><span>Vary: Accept-Encoding</span></span>
<span class="line"><span>X-Cache: HIT</span></span>
<span class="line"><span>Content-Length: 1256</span></span>
<span class="line"><span></span></span>
<span class="line"><span>---response end---</span></span>
<span class="line"><span>200 OK</span></span>
<span class="line"><span>Registered socket 3 for persistent reuse.</span></span>
<span class="line"><span>URI content encoding = &#39;UTF-8&#39;</span></span>
<span class="line"><span>Length: 1256 (1.2K) [text/html]</span></span>
<span class="line"><span>Saving to: &#39;index.html&#39;</span></span></code></pre></div><h3 id="处理-301-响应" tabindex="-1">处理 301 响应 <a class="header-anchor" href="#处理-301-响应" aria-label="Permalink to “处理 301 响应”">​</a></h3><p>200 响应码意味着一切都在预料之中。而 301 响应则表示 URL 已经被永久迁移到了另外一个地方。这是站点管理员的一种常用手段，内容迁移后，为访问旧地址的用户留下寻找新地址的“线索”。<code>wget</code> 会默认跟随<ruby>重定向<rt>redirect</rt></ruby>，这也是大部分情况下用户所希望的。</p><p>当然，你可以使用 <code>--max-redirect</code> 选项，用于控制 <code>wget</code> 默认处理 301 响应重定向的次数。设置为 <code>0</code> 意味着不会自动重定向到新的地址:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget --max-redirect 0 http://iana.org</span></span>
<span class="line"><span>--2021-09-21 11:01:35-- http://iana.org/</span></span>
<span class="line"><span>Resolving iana.org... 192.0.43.8, 2001:500:88:200::8</span></span>
<span class="line"><span>Connecting to iana.org|192.0.43.8|:80... connected.</span></span>
<span class="line"><span>HTTP request sent, awaiting response... 301 Moved Permanently</span></span>
<span class="line"><span>Location: https://www.iana.org/ [following]</span></span>
<span class="line"><span>0 redirections exceeded.</span></span></code></pre></div><p>同时，你也可以设置为其他的数值来控制 <code>wget</code> 能重定向多少次。</p><h3 id="展开-url-缩写" tabindex="-1">展开 URL 缩写 <a class="header-anchor" href="#展开-url-缩写" aria-label="Permalink to “展开 URL 缩写”">​</a></h3>`,37)),e("p",null,[s[1]||(s[1]=n("使用",-1)),s[2]||(s[2]=e("code",null,"--max-redirect",-1)),s[3]||(s[3]=n(" 选项用于在实际访问之前查看 ",-1)),s[4]||(s[4]=e("ruby",null,[n("URL 缩写"),e("rt",null,"shortened URL")],-1)),s[5]||(s[5]=n("非常有用。缩写 URL 可用于用户无法完整拷贝和粘贴一个长 URL 时的",-1)),s[6]||(s[6]=e("ruby",null,[n("印刷媒体"),e("rt",null,"print media")],-1)),s[7]||(s[7]=n("，或是具有字数限制的社交网络（在类似 ",-1)),t(a,{href:"https://opensource.com/article/17/4/guide-to-mastodon"},{default:i(()=>[...s[0]||(s[0]=[n("Mastondon",-1)])]),_:1}),s[8]||(s[8]=n(" 这种现代开源的社交网络上这并不是一个问题）。这种缩写具有一定的风险，因为本质上这些目的地是隐藏的。组合使用 ",-1)),s[9]||(s[9]=e("code",null,"--head",-1)),s[10]||(s[10]=n(" 选项和 ",-1)),s[11]||(s[11]=e("code",null,"--location",-1)),s[12]||(s[12]=n(" 选项来来查看 HTTP 头部并解开最终的目的地，你可以在不加载整个资源的情况下查看到缩写 URL 的完整内容：",-1))]),s[36]||(s[36]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wget --max-redirect 0 &quot;https://bit.ly/2yDyS4T&quot;</span></span>
<span class="line"><span>--2021-09-21 11:32:04-- https://bit.ly/2yDyS4T</span></span>
<span class="line"><span>Resolving bit.ly... 67.199.248.10, 67.199.248.11</span></span>
<span class="line"><span>Connecting to bit.ly|67.199.248.10|:443... connected.</span></span>
<span class="line"><span>HTTP request sent, awaiting response... 301 Moved Permanently</span></span>
<span class="line"><span>Location: http://example.com/ [following]</span></span>
<span class="line"><span>0 redirections exceeded.</span></span></code></pre></div><p>从 <code>Location</code> 开始的倒数第二行输出，展示了实际的目的地。</p><h3 id="使用-wget" tabindex="-1">使用 wget <a class="header-anchor" href="#使用-wget" aria-label="Permalink to “使用 wget”">​</a></h3>`,3)),e("p",null,[s[14]||(s[14]=n("若你开始考虑使用单个命令来实现整个网站访问的过程，",-1)),s[15]||(s[15]=e("code",null,"wget",-1)),s[16]||(s[16]=n(" 可以快速高效的帮你获取互联网上的信息，而不用在图形界面上耗费精力。为了帮你将它构造在你平常的工作流中，我们创建了一个 ",-1)),s[17]||(s[17]=e("code",null,"wget",-1)),s[18]||(s[18]=n(" 常用使用方式和语法清单，包括使用它来查询 API 的概述。",-1)),t(a,{href:"https://opensource.com/downloads/linux-wget-cheat-sheet"},{default:i(()=>[...s[13]||(s[13]=[n("在这里下载 Linux wget 速查表",-1)])]),_:1}),s[19]||(s[19]=n("。",-1))]),s[37]||(s[37]=e("hr",null,null,-1)),e("p",null,[s[21]||(s[21]=n("来源: ",-1)),t(a,{href:"https://opensource.com/article/21/10/linux-wget-command"},{default:i(()=>[...s[20]||(s[20]=[n("https://opensource.com/article/21/10/linux-wget-command",-1)])]),_:1})]),e("p",null,[s[26]||(s[26]=n("作者：",-1)),t(a,{href:"https://opensource.com/users/seth"},{default:i(()=>[...s[22]||(s[22]=[n("Seth Kenlon",-1)])]),_:1}),s[27]||(s[27]=n(" 选题：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[23]||(s[23]=[n("lujun9972",-1)])]),_:1}),s[28]||(s[28]=n(" 译者：",-1)),t(a,{href:"https://github.com/zengyi1001"},{default:i(()=>[...s[24]||(s[24]=[n("zengyi1001",-1)])]),_:1}),s[29]||(s[29]=n(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[25]||(s[25]=[n("wxy",-1)])]),_:1})]),e("p",null,[s[32]||(s[32]=n("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[30]||(s[30]=[n("LCTT",-1)])]),_:1}),s[33]||(s[33]=n(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:i(()=>[...s[31]||(s[31]=[n("Linux中国",-1)])]),_:1}),s[34]||(s[34]=n(" 荣誉推出",-1))])])}const w=l(g,[["render",c]]);export{y as __pageData,w as default};
